const n=(label,value,unit='ratio')=>({label,value,unit,relativeTolerance:['K','degC'].includes(unit)?0:.03,absoluteTolerance:['K','degC'].includes(unit)?.25:1e-7});
const cases=[];
function add(title,domain,prompt,tasks,fields,solution,priorities){
 const id='D'+String(cases.length+1).padStart(3,'0');
 cases.push({id,title,domain,prompt,tasks,fields:fields.map((f,i)=>({...f,key:'n'+i})),solution,
 level:'design',kind:'design',minutes:25,hint:'Sketch the boundary and load path. Estimate the governing limit before calculating.',
 rubric:[priorities[0],priorities[1],'Apply consistent balances, equations, units and signs.','Make a defensible design choice, including a competing alternative.','Describe validation, failure response and limits of the simplified calculation.']});
}

add('Design a 12 MW compute-cooling campus','thermal-fluid',
 'A compute campus puts 12 MW into water at 30→40°C. Use cp=4.18 kJ/(kg K), rho=1000 kg/m³. Six equal rows share flow. Limit main-header velocity to 2.0 m/s. Required loop differential at design flow is 180 kPa; pump efficiency 0.78 and motor efficiency 0.95. Neglect pump heating in the 12 MW duty.',
 ['Draw a primary/secondary or CDU-based scheme and define the boundary.','Find total and row mass flow, minimum hydraulic header ID, and electrical pump input.','Choose a practical pipe size and an N+1 pumping arrangement; justify isolation and control.','Explain how you would commission row balance and respond to loss of a duty pump.'],
 [n('Total mass flow',12e6/(4180*10),'kg/s'),n('Mass flow per row',2e6/(4180*10),'kg/s'),n('Minimum header ID',Math.sqrt(4*(12e6/(4180*10)/1000)/(Math.PI*2))*1000,'mm'),n('Electrical pump input',180000*(12e6/(4180*10)/1000)/(.78*.95)/1000,'kW')],
 'Energy gives m=Q/(cp ΔT)=287.08 kg/s, or 47.85 kg/s per row. Volume flow is 0.28708 m³/s. Dmin=sqrt(4Vdot/(pi v))=427.5 mm; select a commercially available bore with hydraulic margin, then recalculate losses. Pump input is ΔP Vdot/(eta_p eta_m)=69.74 kW. A defensible arrangement is two 50%-capacity duty pumps and one identical standby, if each pump and the common controls are checked at both normal and failure operating points. Standby count alone does not prove availability. Include strainers, isolation, expansion/pressurization, branch balance, monitoring, and a heat-rejection boundary. Verify vendor curves, minimum flows, motor ratings, failover transients and actual site ambient limits.',
 ['Close the 12 MW balance and size both shared and per-row flow.','Distinguish velocity-based bore, operating pressure loss and actual pump/system intersection.']);

add('Size an equipment-support beam for two limits','structure',
 'A simply supported 4.0 m beam carries a 3 kN/m uniform load and an 8 kN midspan point load. E=200 GPa, allowable bending stress=150 MPa and deflection limit=L/400. Neglect self-weight for this first pass. Both loads act vertically in the same plane.',
 ['Draw the free-body, shear and bending diagrams.','Find reactions, maximum moment, minimum section modulus and minimum second moment of area.','Explain how to select one real section that satisfies both constraints.','List the load cases and local checks missing from this first pass.'],
 [n('Reaction at each support',10,'kN'),n('Maximum moment',14,'kN.m'),n('Minimum section modulus',14e3/150e6*1e6,'cm3'),n('Minimum second moment of area',(5*3000*4**4/384+8000*4**3/48)/(200e9*.01)*1e8,'cm4')],
 'Each reaction is (3×4+8)/2=10 kN. The symmetric maximum moment is wL²/8+PL/4=14 kN m. Smin=M/sigma_allow=93.33 cm³. Superposition gives delta=[5wL⁴/384+PL³/48]/(EI); with delta_allow=10 mm, Imin=1033.3 cm⁴. A real section must satisfy both simultaneously about the correct axis. Add self-weight and iterate. Check shear, lateral-torsional buckling, bearing, connections, fatigue, equipment alignment, vibration, seismic/handling loads and support restraint. Below-yield stress alone is not an alignment qualification.',
 ['Use superposition and the correct boundary conditions.','Separate section-modulus strength from second-moment stiffness requirements.']);

add('Recover a methane line that begins flashing','cryo',
 'Methane flows at 2.0 kg/s and 111 K. Distributed external heat input is 16 kW. Use liquid cp=3.5 kJ/(kg K) and hfg=510 kJ/kg. A supplied property assessment gives saturation temperature 113 K at the controlled outlet pressure. Neglect changes in kinetic and potential energy. For the final minimum-flow calculation, hold that outlet pressure fixed even when flow changes.',
 ['Calculate the hypothetical all-liquid outlet temperature.','Calculate the equilibrium outlet vapor quality using the supplied local saturation state.','Find the mass flow at incipient saturation with the same heat input and outlet pressure.','Propose three distinct remedies and explain why pressure loss is not a second external heat input.'],
 [n('Hypothetical all-liquid outlet temperature',111+16/(2*3.5),'K'),n('Equilibrium vapor quality',100*(16-2*3.5*2)/(2*510),'percent'),n('Flow at incipient saturation',16/(3.5*2),'kg/s')],
 'The all-liquid extrapolation is 113.286 K, above the supplied 113 K saturation limit. Heating liquid to 113 K consumes 14 kW; the remaining 2 kW gives x=2/(2×510)=0.001961, or 0.1961% by mass. Incipient saturation requires m=16/(3.5×2)=2.286 kg/s under the deliberately fixed outlet-pressure assumption; positive subcooling requires more flow or another change. Remedies include reducing heat leak, increasing pressure where allowed, lowering inlet temperature, or changing transfer/control conditions. Recompute the pressure profile and properties in a real design. Friction destroys mechanical availability; it does not add another external Q term to the total-energy balance. A small mass quality can still give substantial void fraction.',
 ['Use local pressure-dependent saturation rather than inlet saturation.','Do not double-count friction as external heating or infer void fraction from mass quality.']);

const qp=Math.sqrt((75*1.15**2-10)/.005),hp=75*1.15**2-.002*qp**2;
add('Choose a variable-speed pump operating point','thermal-fluid',
 'A water pump has H=75−0.002Q² at reference speed. The system is H=10+0.003Q². H is metres and Q is m³/h. Speed may increase to 1.15 times reference; apply affinity scaling to the whole pump curve. rho=1000 kg/m³, g=9.81 m/s², pump efficiency=0.75 and motor efficiency=0.95, both held constant only for this exercise.',
 ['Find the reference operating flow and head.','Derive the entire speed-shifted pump curve and solve the new intersection.','Find electrical input at the faster operating point.','Explain why Q does not simply scale with speed here, and identify necessary vendor checks.'],
 [n('Reference operating flow',Math.sqrt(65/.005),'m3/h'),n('Faster operating flow',qp,'m3/h'),n('Faster operating head',hp,'m'),n('Faster electrical input',1000*9.81*qp/3600*hp/(.75*.95)/1000,'kW')],
 'At reference speed, 75−0.002Q²=10+0.003Q² gives Q=114.02 m³/h and H=49 m. With speed ratio r, Hnew(Q)=r² Hold(Q/r)=75r²−0.002Q². At r=1.15 the intercept is 99.1875 m, giving Q=sqrt(89.1875/0.005)=133.56 m³/h and H=63.5125 m. Electrical power is rho g Q H/(eta_p eta_m), using Q in m³/s. Fixed static head prevents a simple 1.15 multiplier on operating flow. Check NPSHr, motor and VFD limits, operating region, minimum flow, efficiency changes and maximum pressure; a mathematical intersection is not equipment qualification.',
 ['Transform the curve at fixed physical flow, not just its original operating point.','Account for static head and motor input separately from hydraulic power.']);

const lm=3/Math.log(13/10);
add('Select an exchanger with fouling and approaches','thermal-fluid',
 'Transfer 2.0 MW in counterflow. Hot water is 45→35°C and cold water is 25→32°C. cp=4.18 kJ/(kg K). Clean U=900 W/(m² K), configuration factor F=0.95. Added fouling resistance is 0.00030 m² K/W. Treat the stated terminal profile as the required design target for both area calculations.',
 ['Find each stream mass flow and the two terminal differences.','Find LMTD and clean area.','Find fouled U and the area required to retain the target duty and terminal profile.','Choose a plausible exchanger type and discuss pressure loss, materials, cleanability and flow distribution.'],
 [n('Hot-side mass flow',2e6/(4180*10),'kg/s'),n('Cold-side mass flow',2e6/(4180*7),'kg/s'),n('LMTD',lm,'K-rise'),n('Clean area',2e6/(900*.95*lm),'m2'),n('Fouled required area',2e6*(1/900+.0003)/(.95*lm),'m2')],
 'Hot and cold mass flows are 47.85 and 68.35 kg/s. Counterflow terminal differences are 45−32=13 K and 35−25=10 K, so LMTD=3/ln(13/10)=11.43 K. Aclean=Q/(UF LMTD). Fouled U=1/(1/900+0.00030)=708.66 W/(m² K); retaining the same target temperatures and duty requires 27% more area. If area and both mass flows were instead fixed, fouling would change outlet temperatures: do not hold every variable fixed and claim a physically independent new duty. A gasketed plate exchanger may be defensible for suitable clean water and service conditions, but selection needs pressure, compatibility, access, reliability and vendor rating data.',
 ['Pair counterflow terminal temperatures correctly.','Treat fouling as an added resistance and preserve a consistent rating/design boundary.']);

const rhoCH4=430,nh=30000/(rhoCH4*9.81)+1.5-.8;
add('Design the methane pump suction arrangement','cryo',
 'A methane tank surface is at 2.00 bar absolute. Liquid vapor pressure is 1.70 bar absolute and density is 430 kg/m³. Pump inlet is 1.5 m below the surface; suction losses are 0.8 m. NPSHr=3.5 m and the specified additive margin is 1.5 m. Use g=9.81 m/s² and the same liquid density throughout.',
 ['Calculate NPSHa and assess the specified margin.','Find the minimum tank surface pressure satisfying that margin.','Assess a 0.20 bar decrease in surface pressure with temperature unchanged.','Choose layout/control changes and identify assumptions that must be tested during cooldown and low-level operation.'],
 [n('NPSH available at initial state',nh,'m'),n('Minimum surface pressure for specified margin',(170000+430*9.81*(5+.8-1.5))/1e5,'bar'),n('NPSH after pressure decrease',10000/(430*9.81)+.7,'m')],
 'NPSHa=(psurface−pv)/(rho g)+z−hloss=7.812 m. The specified threshold is 3.5+1.5=5.0 m, so the initial state passes. Minimum surface pressure is pv+rho g(5+0.8−1.5)=1.8814 bar absolute. After a 0.20 bar pressure decrease, NPSHa falls to 3.071 m and fails the specified threshold, even before added uncertainty. Consider pump elevation, short/large suction piping, restrictions, minimum level, inlet conditioning and allowed pressurization. Validate actual saturation properties, transient states and vendor cryogenic pump requirements. Do not substitute discharge pressure or gauge pressure into the vapor-pressure subtraction.',
 ['Use absolute pressures and the correct elevation sign.','Assess the required additive margin over the full operating envelope.']);

add('Lay out a feed-to-storage methane plant','cryo',
 'A hypothetical facility receives an average 1000 tonnes/day of natural gas containing 90% methane by mass. Methane recovery is 98%. Train on-stream availability is 90%; a feed buffer allows the on-stream train to catch up. Store 36 hours of average recovered methane. Use liquid density 430 kg/m³ and maximum liquid fraction 90% of geometric volume; ignore heel.',
 ['Find average recovered methane and required on-stream feed capacity.','Size geometric liquid storage for the stated inventory.','Draw pretreatment, liquefaction, separation/storage and boil-off handling blocks.','Explain which purity and contamination specifications are missing; compare nitrogen expansion and mixed-refrigerant routes under explicit constraints.'],
 [n('Average recovered methane',882,'t/day'),n('On-stream gas feed capacity',1000/.9,'t/day'),n('Geometric liquid storage',882*1.5*1000/(430*.9),'m3')],
 'Recovered methane component is 1000×0.90×0.98=882 t/day on a calendar-average basis. With buffering and 90% availability, on-stream feed capacity must be 1111.1 t/day. Storage is 882×1.5=1323 t of liquid methane component; Vgeom=1,323,000/(430×0.90)=3418.6 m³ under the pure-component inventory approximation. A defensible train addresses water, CO2, heavy hydrocarbons and any other specified contaminants before cold equipment, then compression/precooling/liquefaction, relevant separation and boil-off management. Liquefaction alone does not guarantee methane purity. Actual LNG composition changes density, duty, phase behavior and storage estimates. Availability derating requires compatible upstream buffering and catch-up operation.',
 ['Keep component recovery, availability and calendar inventory on distinct bases.','Explain pretreatment and product composition rather than equating LNG with pure methane.']);

add('Plan LOX line cooldown and a useful test','cryo',
 'A 500 kg steel transfer assembly must cool from 293 to 93 K. Use average steel cp=0.45 kJ/(kg K). For a deliberately latent-only LOX estimate, use hfg=213 kJ/kg. Desired cooldown time is 600 s and external heat leak is 5 kW throughout. Ignore fluid holdup and hardware other than the stated steel mass.',
 ['Estimate steel energy removal and liquid-equivalent use including the heat leak.','Find the average latent-equivalent flow over 600 s.','Explain why this is not a reliable transient flow prescription.','Design a cooldown validation test with measurable completion and stop criteria.'],
 [n('Steel cooldown energy',500*.45*200,'kJ'),n('Total liquid-equivalent consumption',(500*.45*200+5*600)/213,'kg'),n('Average latent-equivalent rate',(500*.45*200/600+5)/213,'kg/s')],
 'Steel sensible energy is 45,000 kJ. Heat leak adds 3000 kJ, giving a latent-equivalent total of 225.35 kg and an average rate of 80/213=0.3756 kg/s. This bookkeeping estimate neglects real vapor sensible heating, liquid carryover, axial gradients, supports, fittings and transient boiling regimes. Film boiling, unstable flow and phase separation can make an imposed average rate misleading. Measure distributed wall/fluid temperatures, pressure and differential pressure, inlet/outlet mass inventory and vent conditions. Define stable outlet subcooling and wall approach criteria, permitted pressure/thermal-gradient limits, staged valve actions and safe stop conditions. Use oxygen-compatible, clean equipment and an approved test procedure.',
 ['Include the external heat load without hiding the latent-only approximation.','Propose a transient measurement plan rather than treating the average as an operating instruction.']);

const flowReq=(.018/((70-35)/1200-.012))**1.25;
add('Co-design a cold plate and flow requirement','thermal-fluid',
 'One chip dissipates 1200 W. Solid/contact resistance is 0.012 K/W. Convective resistance is 0.018 K/W at reference flow and scales as flow^-0.8. Junction limit is 70°C. Local coolant initially is 30°C, then may rise to 35°C. Supplier minimum flow is 0.75 times reference. Assume the same local resistance model remains valid.',
 ['Find reference-flow junction temperature at 30°C.','Find minimum flow fraction at 35°C and compare against supplier minimum.','At that fraction, find hydraulic-power multiplier if system loss scales with flow² and efficiency stays fixed.','Explain how manifold maldistribution and local versus bulk coolant affect qualification.'],
 [n('Reference junction temperature at 30 C',66,'degC'),n('Required flow / reference at 35 C',flowReq),n('Hydraulic-power multiplier',flowReq**3)],
 'Reference resistance is 0.030 K/W, so Tj=30+1200×0.030=66°C. At 35°C, total allowable resistance is 35/1200=0.029167 K/W. Convection may use 0.017167 K/W after subtracting the solid/contact term. Solve 0.018 f^-0.8=0.017167 to get f≈1.061. This exceeds the 0.75 supplier minimum. With the stated resistance model, hydraulic power scales as f³, about 1.19 times reference. A bulk water energy balance does not qualify the local hotspot. Check contact variation, actual cold-plate map, viscosity, pressure allowance, parallel distribution, sensor placement and local coolant temperatures.',
 ['Combine series resistances and respect the supplier lower bound.','Use the local coolant boundary and distinguish thermal response from hydraulic power.']);

add('Size a ride-through buffer and its circulation supply','thermal-fluid',
 'An 8 MW cooling load must run for 60 s without refrigeration. Water may warm 6 K, cp=4.18 kJ/(kg K), rho=1000 kg/m³. Only 80% of geometric tank volume is usable in the event. Circulation must continue and draws 20 kW from an independent electrical source. Neglect pump heating in the 8 MW thermal load.',
 ['Calculate the required geometric buffer volume.','Calculate circulation electrical energy for the event.','Design the tank connection and failover sequence.','Explain why the tank is ineffective if flow stops and which transient temperatures need validation.'],
 [n('Geometric buffer volume',8e6*60/(4180*6*1000*.8),'m3'),n('Circulation electrical energy',20*60/3600,'kWh')],
 'Required accessible water volume is Qt/(rho cp ΔT)=19.139 m³. Divide by 0.80 usable fraction to obtain 23.923 m³ geometric volume. Circulation needs 20×60/3600=0.333 kWh, before electrical conversion losses and reserve margin. Storage is useful only if hydraulic routing delivers the inventory to the protected loads. Specify valves/checks, standby circulation, controls and sensor power, minimum usable level, mixing/stratification assumptions and automatic shutdown if flow is not recovered. Prove the thermal response at the most vulnerable components rather than using the average tank temperature alone.',
 ['Separate usable thermal volume from geometric volume.','Treat circulation and control power as necessary parts of ride-through.']);

add('Check a pressure shell beyond a hoop formula','structure',
 'A thin closed cylindrical shell has differential pressure 3 MPa, diameter 0.60 m and wall 6 mm. Use nominal membrane stresses and von Mises for a ductile material. Supplied allowable equivalent stress is 120 MPa. Ignore weld efficiency, corrosion allowance and local loads only for this first pass.',
 ['Find hoop and axial stress and the plane-stress von Mises value.','Find minimum wall thickness satisfying that supplied criterion.','Assess whether the thin-wall approximation is reasonable.','List the extra information needed before designing or purchasing the vessel.'],
 [n('Hoop stress',150,'MPa'),n('Axial stress',75,'MPa'),n('Von Mises membrane stress',Math.sqrt(150**2-150*75+75**2),'MPa'),n('Minimum wall under supplied criterion',Math.sqrt(3)*3e6*.6/(4*120e6)*1000,'mm')],
 'Hoop=pD/(2t)=150 MPa; axial=pD/(4t)=75 MPa. Von Mises is sqrt(150²−150×75+75²)=129.90 MPa, above the supplied 120 MPa limit. The corresponding thickness is sqrt(3)pD/(4 sigma_allow)=6.495 mm. This remains geometrically thin relative to diameter, but a membrane pass is not a code vessel design. Material temperature limits, welds, fabrication tolerances, openings, fatigue, external pressure, supports, corrosion, inspection, relief and applicable requirements remain. A room-temperature material value must not be silently used for cryogenic qualification.',
 ['Use the closed-end biaxial stress state.','Distinguish a supplied textbook criterion from a complete pressure-boundary design.']);

const areaTube=Math.PI/4*(.08**2-.07**2),iTube=Math.PI/64*(.08**4-.07**4),pcr=190e9*iTube*Math.PI**2/2.4**2;
add('Check a slender cryogenic support tube','structure',
 'A straight pinned-pinned tube is 2.4 m long, OD=80 mm, ID=70 mm. Use E=190 GPa and yield=240 MPa for the stated temperature. Service axial compression is 50 kN. Required factors are 3 against ideal Euler buckling and 2 against simple axial yield. Assume concentric load for this model.',
 ['Calculate area, second moment, axial stress and Euler critical load.','Find each allowable load and the governing one.','Assess the 50 kN service case and the sensitivity to effective length.','Explain why imperfections, joints, local shell buckling and heat leak still matter.'],
 [n('Axial service stress',50000/areaTube/1e6,'MPa'),n('Euler critical load',pcr/1000,'kN'),n('Governing allowable load',Math.min(pcr/3,240e6*areaTube/2)/1000,'kN')],
 'A=pi(Do²−Di²)/4 and I=pi(Do⁴−Di⁴)/64. The nominal service stress is about 42.44 MPa. Euler Pcr=pi²EI/(KL)² with K=1. Divide that result by 3, and compare with A sigma_y/2. The smaller allowable governs and exceeds the stated 50 kN in this idealized check. Effective length enters squared, so uncertain end restraint can reverse the conclusion. Euler validity needs an appropriate slenderness/inelastic assessment; add initial bow, eccentricity, local tube instability, thermal contraction, joint loads and actual temperature-dependent properties. The same tube geometry also creates a thermal conduction path.',
 ['Compare independent yield and stability allowables.','Justify end conditions and recognize imperfection and thermal tradeoffs.']);

add('Choose a cooling temperature using work and constraints','cycle',
 'A 6 MW refrigerator rejects to a uniform 310 K reservoir. Compare cold-reservoir temperatures 280 and 270 K. Actual COP is stipulated to be 45% of Carnot COP in both cases. Ignore all other power. The protected equipment can accept 280 K if humidity and its own local temperature limits are met.',
 ['Calculate actual COP, compressor input and rejection at each cold temperature.','Find the compressor-power difference.','Choose a temperature and state the conditions that could change your choice.','Explain the limits of using a single-reservoir Carnot fraction to rate real chillers.'],
 [n('Actual COP at 280 K',.45*280/(310-280)),n('Input at 280 K',6/(.45*280/30),'MW'),n('Input at 270 K',6/(.45*270/40),'MW'),n('Additional input at 270 K',6/(.45*270/40)-6/(.45*280/30),'MW')],
 'Carnot COP=Tc/(Th−Tc). Actual COP is 4.20 at 280 K and 3.0375 at 270 K. Inputs are 1.4286 and 1.9753 MW; rejection equals 6 MW plus each input. The colder case adds 0.5467 MW under this stipulated model. Choose the warmer feasible supply if equipment thermal resistance, approach temperatures, flow limits, humidity/condensation and operating envelope permit it. A real evaporator/condenser has changing fluid temperatures, pressure drops, lift-dependent compressor efficiency and part-load controls. The exercise compares defined reservoir boundaries, not detailed fluid-loop setpoints.',
 ['Use absolute temperatures and include compressor work in rejection.','Choose a feasible temperature using equipment constraints rather than efficiency alone.']);

const rB=4,kB=1.4,cpB=1.04,t2=280+(280*rB**((kB-1)/kB)-280)/.8,t4=300-.85*(300-300/rB**((kB-1)/kB));
add('Analyze a simple reverse-Brayton refrigerator','cycle',
 'An ideal-gas nitrogen loop leaves its load exchanger at T1=280 K and enters a compressor. Pressure ratio=4, k=1.4, cp=1.04 kJ/(kg K), compressor isentropic efficiency=0.80. An aftercooler sets T3=300 K. Expander isentropic efficiency=0.85; its work is fully recovered mechanically. It expands back to low pressure. Ignore pressure losses and heat leakage. This is a non-regenerative toy cycle.',
 ['Draw the four states and directions of heat/work.','Find T2, T4, cold duty per kg and net shaft work per kg.','Calculate cycle COP and flow for a 500 kW load.','Explain what recuperation changes and why this toy cycle is not automatically suitable for methane liquefaction.'],
 [n('Compressor outlet T2',t2,'K'),n('Expander outlet T4',t4,'K'),n('Cycle COP',cpB*(280-t4)/(cpB*((t2-280)-(300-t4)))),n('Nitrogen flow for 500 kW',500/(cpB*(280-t4)),'kg/s')],
 'Use T2s=T1 r^((k−1)/k), T2=T1+(T2s−T1)/eta_c. For expansion, T4s=T3/r^((k−1)/k) and T4=T3−eta_t(T3−T4s). Cold duty per kg is cp(280−T4); compressor work is cp(T2−280), expander recovery cp(300−T4), and COP=qL/(wc−wt). Required flow is 500/qL with kJ/kg and kW. The coldest state in this non-regenerative calculation is nowhere near methane liquefaction temperature. Recuperation changes the state temperatures and must be solved as part of a closed energy balance; it is not a free duty credit. Check real properties, pressure losses, phase limits, turbomachinery and heat-exchanger pinches.',
 ['Use the different compressor and turbine efficiency definitions.','Subtract recovered expander work and close the specified four-state cycle.']);

add('Compare throttling with work-producing expansion','cycle',
 'A hypothetical phase-compatible expansion device feeds an equilibrium separator. At separator pressure hf=80 and hg=480 kJ/kg. Inlet enthalpy is 110 kJ/kg and feed is 2 kg/s. An adiabatic throttle has no shaft work. An alternative device delivers 20 kJ/kg shaft work, with negligible changes in kinetic/potential energy. Use the same enthalpy reference throughout.',
 ['Calculate separator vapor quality and liquid production for the throttle.','Calculate outlet enthalpy, liquid production and shaft output for the alternative.','Explain why the alternative cannot be assumed to be an ordinary dry-gas turbine.','Place the comparison in a Linde/Claude-style flowsheet and identify missing equipment data.'],
 [n('Throttle vapor quality',100*(110-80)/(480-80),'percent'),n('Throttle liquid rate',2*(1-(110-80)/400),'kg/s'),n('Alternative liquid rate',2*(1-(90-80)/400),'kg/s'),n('Alternative shaft output',40,'kW')],
 'For throttling, hout=hin=110 and x=(110−80)/400=0.075, so liquid rate is 2×0.925=1.85 kg/s. The work-producing device has hout=110−20=90, x=0.025 and liquid rate 1.95 kg/s; shaft output is 40 kW. This comparison explicitly assumes a phase-compatible device. A conventional gas turboexpander may not tolerate wet expansion; real Claude layouts often expand a suitable vapor side stream instead. Enthalpy/phase constraints, component efficiency, recuperator pinch, pressure losses and full compression power determine whether a design is practical.',
 ['Use enthalpy conservation for a throttle and the shaft-work term for an expander.','Respect the stated phase-compatibility assumption and actual machine limitations.']);

add('Close the split in a simplified Claude flowsheet','cycle',
 'A toy Claude-type cold box has 2.0 kg/s circulating feed. Twenty percent is diverted through a gas expander and returns as low-pressure vapor; its measured specific shaft output is 10 kJ/kg. The remaining stream reaches a JT valve at h=50 kJ/kg. At separator pressure hf=0 and hg=200 kJ/kg. Do not infer net fresh feed or plant electrical COP from this circulating-stream model.',
 ['Sketch compression, recuperation, the expander split, JT valve and separator return.','Find expander shaft output, JT vapor fraction and separator liquid production.','State which balances and properties are still needed for complete plant sizing.','Explain extra concerns if the working process is hydrogen near 20 K.'],
 [n('Expander shaft output',.2*2*10,'kW'),n('JT vapor fraction',25,'percent'),n('Separator liquid rate',2*.8*.75,'kg/s')],
 'The expander carries 0.40 kg/s and produces 4.0 kW. The JT branch carries 1.60 kg/s; its quality is (50−0)/(200−0)=0.25, giving 1.20 kg/s liquid and 0.40 kg/s separator vapor. The total low-pressure return also contains the 0.40 kg/s expander stream. These are local flows, not a complete fresh-feed/product steady-state balance. Close recuperator energy, compression/intercooling, heat leak, pressure losses, phase limits and mass recycling. Hydrogen needs a real-property inversion/precooling assessment and ortho-para conversion heat management, along with materials and purity constraints; methane properties cannot be substituted.',
 ['Apply the split before calculating separator production.','Identify the gap between circulating local flows and whole-plant mass/energy closure.']);

add('Choose an LNG cycle when cost conflicts with turndown','cycle',
 'Both hypothetical LNG routes can make 100 t/day while online and run 90% of the year. For the first-pass financial estimate, assume full-rate operation during all online hours. Nitrogen expansion uses 0.80 kWh/kg and costs $3 million. Single mixed refrigerant uses 0.55 kWh/kg and costs $5 million. Electricity is $0.10/kWh; use 365 days/year. Separately, the actual operating requirement includes 20% load with no product buffer: N2 can operate at 10%, but the supplied SMR design has a 40% minimum. The financial rule is simple payback below 3 years.',
 ['Calculate annual energy savings and SMR incremental simple payback.','Decide whether the cheaper-energy option is feasible as stated.','Propose a change that could make it feasible and state its additional assumptions.','Discuss controls, refrigerant handling, startup and ambient sensitivity.'],
 [n('Annual SMR electricity saving',100000*365*.9*(.80-.55)/1000,'MWh'),n('Incremental simple payback',2e6/(100000*365*.9*.25*.1),'year')],
 'The stipulated full-rate financial estimate gives annual product of 32.85 million kg. SMR saves 8,212.5 MWh/year, worth $821,250/year, so its incremental simple payback is 2.435 years. It passes that first-pass financial threshold but fails the stated 20% operating demand without buffering, multiple trains or another engineered operating strategy. The N2 route is feasible on the stated turndown criterion. Do not choose a technically infeasible option from payback alone. A real variable-load schedule changes annual savings and payback. Storage, staged smaller trains or qualified recirculation can alter feasibility, cost, energy and availability; quantify those additions rather than assuming they are free.',
 ['Calculate costs on the on-stream annual product basis.','Apply the turndown constraint before ranking feasible alternatives.']);

add('Design a seasonal economizer mode','cycle',
 'A 10 MW cooling load has a 25°C supply requirement. A dry-cooler/economizer path needs a 5 K ambient-to-supply approach. Weather data provide 4000 h/year below the qualifying ambient threshold and 4760 h/year above it. A chiller has COP 5 in the mechanical mode. Circulation/fan power is stipulated to total 0.20 MW in either mode and also in the all-chiller baseline. Ignore other loads.',
 ['Find the highest qualifying dry-bulb temperature.','Calculate annual electrical energy with the economizer and the baseline saving.','Draw the changeover/bypass arrangement and specify a control deadband.','Discuss freeze protection, water quality, return-temperature dependence and the difference from a wet-bulb tower.'],
 [n('Highest qualifying ambient dry bulb',20,'degC'),n('Annual electrical energy',10/5*4760+.2*8760,'MWh'),n('Annual saving versus all-chiller baseline',10/5*4000,'MWh')],
 'With the supplied single approach, 25−5=20°C is the maximum qualifying dry bulb. Compressor energy is (10/5)×4760=9520 MWh; auxiliaries use 0.20×8760=1752 MWh. Total is 11,272 MWh versus 19,272 MWh for the baseline, a saving of 8000 MWh/year. Real economizer capacity depends on UA, flow and both terminal temperatures, not just a label on outdoor temperature. Define bypass, isolation, deadband, stable staging, freeze protection and failure fallback. A tower is governed by wet bulb plus approach, whereas this stated dry-cooler threshold uses dry bulb.',
 ['Count auxiliary power in both baseline and proposed operation.','Connect qualifying weather hours to an explicit approach and hydraulic/control arrangement.']);

const radiation=.04*5.67e-8*20*(300**4-90**4),supportQ=4*.3*.0001*210/.3;
add('Budget radiation and support heat leaks together','cryo',
 'A 20 m² gray cold surface at 90 K sees a much larger black 300 K enclosure, view factor 1, effective surface emissivity 0.04. Use sigma=5.67e-8 W/(m² K⁴). Four supports each have area 100 mm², length 0.30 m and mean conductivity 0.30 W/(m K). For a latent-only LOX equivalent, hfg=213 kJ/kg. Ignore other heat paths.',
 ['Calculate radiation and total support conduction separately.','Find their combined latent-equivalent boil-off per hour.','Choose which heat path to investigate first and propose a design change.','Discuss why reducing support area can threaten strength/stability and why an emissivity surrogate does not validate MLI.'],
 [n('Radiative heat input',radiation,'W'),n('Total support heat input',supportQ,'W'),n('Combined latent-equivalent boil-off',(radiation+supportQ)/213000*3600,'kg/h')],
 'Radiation is epsilon sigma A(Th⁴−Tc⁴), about 364.44 W. Supports contribute 4 k A ΔT/L=0.084 W. The combined latent-only equivalent is about 6.16 kg/h. Radiation dominates this deliberately specified model. Consider shields, insulation design, vacuum performance and view factors; establish a measured heat budget. The specified gray-body emissivity is not an MLI material correlation. A support redesign needs mechanical and thermal checks together; a smaller area can increase stress, movement and instability. Include penetrations, residual gas, piping and instrumentation in a complete budget.',
 ['Use fourth-power absolute-temperature radiation and sum parallel heat paths.','Prioritize from a quantified budget while preserving support load capacity.']);

const cr=8/12,ntu=16/8,eff=(1-Math.exp(-ntu*(1-cr)))/(1-cr*Math.exp(-ntu*(1-cr))),hxq=eff*8*40;
add('Rate a counterflow exchanger from UA','thermal-fluid',
 'An ideal counterflow exchanger has hot/cold heat-capacity rates 12 and 8 kW/K, inlet temperatures 60 and 20°C, and UA=16 kW/K. Both streams remain single-phase; properties and UA are constant. Outlet temperatures are unknown.',
 ['Use effectiveness-NTU rather than assuming the outlet temperatures.','Find duty, both outlet temperatures and minimum terminal approach.','Explain whether a cold outlet warmer than the hot outlet violates thermodynamics in counterflow.','Describe what changes if fouling reduces UA or one branch loses flow.'],
 [n('Exchanger effectiveness',eff),n('Transferred heat',hxq,'kW'),n('Hot outlet',60-hxq/12,'degC'),n('Cold outlet',20+hxq/8,'degC')],
 'Cmin=8, Cmax=12 kW/K, Cr=2/3 and NTU=2. Counterflow effectiveness is [1−exp(−NTU(1−Cr))]/[1−Cr exp(−NTU(1−Cr))]. Duty is epsilon Cmin(60−20). Then Th,out=60−Q/12 and Tc,out=20+Q/8. Check both terminal differences: 60−Tc,out and Th,out−20 must remain positive. Cold outlet can exceed hot outlet because they are at opposite ends; there is no forbidden local temperature crossing. Reduced UA reduces effectiveness at fixed inlet conditions and capacity rates. Recalculate operating points rather than claiming every temperature remains fixed.',
 ['Use Cmin, capacity ratio and NTU consistently.','Check local terminal approaches rather than comparing opposite-end outlet temperatures alone.']);

const kg=1.3,rg=.518,cpg=kg*rg/(kg-1),oneW=2*cpg*300*(8**((kg-1)/kg)-1)/.75,twoW=2*2*cpg*300*((Math.sqrt(8))**((kg-1)/kg)-1)/.75;
add('Size staged methane compression and intercooling','cycle',
 'Treat methane as ideal gas with k=1.30 and R=0.518 kJ/(kg K). Compress 2 kg/s from 5 to 40 bar absolute. Inlet is 300 K. Each stage has isentropic efficiency 0.75. Compare one stage with two stages having equal pressure ratios and perfect intercooling back to 300 K. An aftercooler also returns the final product to 300 K. Ignore pressure losses and motor losses.',
 ['Find cp and the two-stage intermediate pressure.','Calculate total shaft input for each arrangement.','Find total intercooler-plus-aftercooler heat rejection for the two-stage train.','Discuss real-gas corrections, discharge temperature, condensate and where equal ratios cease to be optimum.'],
 [n('Two-stage intermediate absolute pressure',Math.sqrt(5*40),'bar'),n('One-stage shaft input',oneW,'kW'),n('Two-stage shaft input',twoW,'kW'),n('Two-stage total cooling duty',twoW,'kW')],
 'cp=kR/(k−1)=2.2447 kJ/(kg K). Equal stage ratio is sqrt(8), so intermediate pressure is sqrt(5×40)=14.142 bar absolute. For each stage w=cp Tin[r^((k−1)/k)−1]/eta. Multiply by mass flow, and sum both stages for the staged case. Because the overall inlet and final aftercooler outlet are both 300 K for an ideal gas, net product enthalpy change is zero: all shaft input leaves in the combined coolers. This does not make each cooler duty equal. Real gas, pressure drops, stage efficiency maps, different cooling temperatures and separation constraints can shift the optimum.',
 ['Use the geometric intermediate pressure only under the stated equal-stage assumptions.','Close the overall compressor-and-cooler energy balance.']);

add('Assess a cooldown-induced vacuum load','structure',
 'A rigid sealed 2 m³ vessel contains ideal nitrogen at 1.0 bar absolute and 300 K. It cools uniformly to 100 K without losing gas. Outside pressure stays 1.0 bar. Use R=296.8 J/(kg K). Do not assume an internal-pressure rating proves external-pressure capacity.',
 ['Find trapped gas mass, final absolute pressure and inward differential pressure.','Draw the shell/support pressure loading.','Explain which instability mechanism can govern and what geometry/material information is missing.','Propose a compatible operating or hardware mitigation and a verification plan.'],
 [n('Trapped nitrogen mass',1e5*2/(296.8*300),'kg'),n('Final absolute pressure',1/3,'bar'),n('Inward differential pressure',2/3,'bar')],
 'Mass is pV/(RT)=2.246 kg. With fixed mass and volume, p/T is constant, giving 0.3333 bar absolute at 100 K and 0.6667 bar net inward loading. External-pressure shell buckling is a distinct limit affected by shell thickness, unsupported length, ovality, stiffeners, openings and temperature-dependent properties. An internal hoop-stress check does not qualify it. Potential mitigations include a vacuum-rated shell or a qualified, compatible pressure-management arrangement. A vacuum-breaker decision must consider product purity, gas compatibility and the actual hazard; do not prescribe uncontrolled air admission to a cryogenic process.',
 ['Use absolute pressure and identify the inward differential.','Treat external-pressure instability separately from internal membrane stress.']);

add('Size the thermal-expansion demand in a blocked line','thermal-fluid',
 'A rigid liquid-full 0.10 m³ water section is isolated at 5 bar gauge. Uniform temperature rises at 0.020 K/s. Use volumetric expansion coefficient beta=3.0e-4/K and bulk modulus B=2.2 GPa; neglect pipe compliance. A hypothetical relief threshold is 10 bar gauge. For a constant-pressure thermal relief estimate, use the displaced liquid volume rate beta V dT/dt.',
 ['Find constrained pressure-rise rate and ideal time to threshold.','Find constant-pressure thermal-expansion discharge demand.','Draw the protected blocked-in segment and identify credible isolation configurations.','Explain why this displaced-volume calculation does not determine a certified relief valve.'],
 [n('Constrained pressure-rise rate',2.2e9*.0003*.02/1e5,'bar/s'),n('Ideal time to threshold',5/(2.2e9*.0003*.02/1e5),'s'),n('Thermal-expansion discharge demand',.0003*.10*.02*1000*60,'L/min')],
 'For the rigid idealization, dp/dt=B beta dT/dt=13,200 Pa/s=0.132 bar/s. A 5 bar rise takes 37.88 s. At constant pressure, displaced volume rate is beta V dT/dt=6e-7 m³/s=0.036 L/min. This is the specified thermal demand, not a full valve selection. Establish fluid properties over the event, heat input, compressibility/compliance, backpressure, phase change, allowable accumulation, setpoint, discharge routing, valve coefficient and applicable requirements. A small volumetric demand can coexist with a rapid pressure rise.',
 ['Distinguish a closed-volume pressure-rate model from an open constant-pressure relief model.','Identify the protected boundary and missing valve qualification conditions.']);

const dl=12e-6*20*180,kpipe=200e9*.0006/20,restraintF=dl/(1/kpipe+1/.5e6);
add('Co-design a contraction restraint and flexible support','structure',
 'A 20 m steel pipe with metal area 600 mm² cools uniformly by 180 K. E=200 GPa and alpha=12e-6/K. Its axial load path contains pipe axial stiffness in series with a support spring of stiffness 0.50 MN/m. The total end-to-end movement is restrained, but the spring can deform. Use a linear elastic axial-only model.',
 ['Find free contraction, pipe stiffness and reaction force.','Find pipe axial stress and compare with fully rigid restraint.','Sketch compatibility and identify whether cooling causes pipe tension or compression.','Explain the effects of anchors, guides, bends and equipment nozzle stiffness in a real piping model.'],
 [n('Free contraction magnitude',dl*1000,'mm'),n('Reaction-force magnitude',restraintF/1000,'kN'),n('Pipe tensile stress',restraintF/.0006/1e6,'MPa'),n('Fully restrained force',200e9*.0006*12e-6*180/1000,'kN')],
 'Free contraction is alpha L |ΔT|=43.2 mm. Pipe stiffness EA/L=6.0 MN/m. Compatibility requires F/kpipe+F/kspring=43.2 mm, so F=19.94 kN and pipe tensile stress is 33.23 MPa. Fully rigid restraint instead gives stress E alpha |ΔT|=432 MPa and force 259.2 kN, before any yielding or nonlinear response. Cooling generates tension when free contraction is opposed. Real pipe bends, support gaps/friction, temperature gradients and nozzle flexibility require a system load-path model; treating every support as an anchor can create unphysical reactions.',
 ['Use series compliance and thermal compatibility.','Identify tensile cooling restraint and compare with the rigid limiting case.']);

add('Diagnose conflicting field measurements','thermal-fluid',
 'A water loop independently absorbs 200 kW. Supply/return thermometers show a 24 K rise; cp=4.18 kJ/(kg K). The installed flowmeter reports 1.0 kg/s. Simultaneous pressure taps show 300 kPa gauge immediately before a filter and 100 kPa gauge immediately after it. A known clean-filter rating is 50 kPa at 2.0 kg/s, with quadratic flow dependence over this range.',
 ['Infer flow from the independent heat balance and compare with the meter.','Calculate the apparent filter resistance multiplier relative to the clean rating at the inferred flow.','Propose an ordered diagnostic plan with independent checks and a safe controlled test.','Explain why neither a blocked filter nor a bad flowmeter is proved by a single reading.'],
 [n('Energy-inferred mass flow',200/(4.18*24),'kg/s'),n('Apparent filter resistance multiplier',200/(50*((200/(4.18*24))/2)**2))],
 'The energy balance implies m=200/(4.18×24)=1.994 kg/s, about twice the meter report. Measured filter loss is 200 kPa; at the inferred flow the clean prediction is about 49.68 kPa, an apparent resistance increase of about 4.03. Multiple inconsistencies may coexist. Verify synchronized steady conditions, independent load boundary, temperature calibration/mixing, meter units and installation, and differential-pressure instrument zero/tap condition. Then compare controlled flow/DP measurements with the clean curve and inspect serviceable hardware under the approved isolation process. Increasing speed blindly can hide the issue and raise system risk.',
 ['Use independent balances to identify incompatible measurements.','Separate an evidence-supported hypothesis from a confirmed diagnosis.']);

const measuredQ=100*4.18*8,uq=Math.sqrt(.03**2+2*(.1/8)**2);
add('Commission a loop using energy closure and uncertainty','thermal-fluid',
 'The independent reference load is 4.000 MW with negligible uncertainty for this exercise. Water flow reads 100 kg/s and two thermometers show an 8 K difference. cp=4.18 kJ/(kg K). Standard flow uncertainty is 3%; each independent temperature has 0.10 K standard uncertainty. Neglect cp uncertainty. All readings represent the same steady boundary.',
 ['Calculate measured duty, energy residual and duty standard uncertainty.','Express the residual in units of that standard uncertainty.','State what this does and does not prove.','Design a measurement/commissioning plan to distinguish bias, mixing, bypass and a boundary mismatch.'],
 [n('Water-side measured duty',measuredQ/1000,'MW'),n('Reference minus water-side residual',4-measuredQ/1000,'MW'),n('Duty standard uncertainty',measuredQ*uq,'kW'),n('Residual / standard uncertainty',(4000-measuredQ)/(measuredQ*uq))],
 'Measured duty is 100×4.18×8=3344 kW, leaving 656 kW residual. Relative standard uncertainty is sqrt(0.03²+(sqrt(2)×0.10/8)²)=0.03482. Absolute standard uncertainty is about 116.46 kW; the discrepancy is about 5.63 standard-uncertainty units. Under the stipulated independent uncertainty model this deserves investigation; it does not identify the cause or prove malicious/broken instrumentation. Check calibration, representative temperature sampling, bypass/mixing, actual power boundary, other heat paths and steady-state inventory. If measurements are correlated or reference uncertainty is non-negligible, revise propagation before interpreting the residual.',
 ['Propagate temperature-difference and flow uncertainties on the stated basis.','Use the residual to guide tests without mistaking it for a diagnosis.']);

add('Evaluate ice storage for a peak tariff','cycle',
 'A 5 MW load runs for a two-hour peak. An ice store supplies it using latent heat 334 kJ/kg, with only 80% of the charged latent energy usable at the load. Ignore sensible storage, pumps and thermal leaks. Off-peak charging COP is 3; direct peak-time chilling COP would be 5. Electricity costs $0.08/kWh off-peak and $0.35/kWh at peak. Ignore capital cost and demand charges.',
 ['Find the charged ice mass and charging electrical energy.','Compare electrical energy and electricity cost against direct peak chilling.','Choose whether storage saves money under these limited assumptions.','Explain why cost savings do not imply energy savings, and list omitted design constraints.'],
 [n('Required charged ice mass',5e6*7200/(334000*.8),'kg'),n('Charging electricity',10/.8/3,'MWh'),n('Cycle electricity-cost saving',2000*.35-(10000/.8/3)*.08,'USD')],
 'Delivered cold energy is 10 MWh=36 GJ. Charge 36/(0.8×0.334)=134,731 kg of ice. Charging requires 12.5 MWh of cold and 4.167 MWh electrical at COP 3, costing $333.33. Direct chilling uses 10/5=2 MWh electrical and costs $700. Storage saves $366.67 per cycle under the given tariffs while consuming 2.167 MWh more electricity. Check ice discharge power, approach temperature, heat-exchanger UA, useful state of charge, tank geometry, expansion, pumping, charging window, cycling, maintenance and capital payback.',
 ['Apply the usable-energy fraction on the correct side of the charge balance.','Separate electricity use, tariff cost and thermal delivery capability.']);

add('Design an orderly thermal ride-through and load shed','thermal-fluid',
 'A circulating system has effective participating thermal capacitance 50 MJ/K. Initial temperature is 30°C; its maximum permitted average temperature is 45°C. Compute load is 5.0 MW and circulation adds 0.05 MW to this same boundary. Refrigeration fails completely, but circulation continues. Ignore other heat rejection. Detection plus actuation consumes 15 s. An immediate 20% compute load shed reduces compute power to 4.0 MW.',
 ['Find ideal time to the temperature limit without shedding.','Find the remaining response time after detection/actuation.','Find time to the limit if the 20% shed happened immediately at failure.','Explain the difference between this average-inventory limit and local chip protection, and propose a staged fail-safe.'],
 [n('Unmitigated time to limit',50*15/5.05,'s'),n('Remaining time after 15 s delay',50*15/5.05-15,'s'),n('Time with immediate 20 percent compute shed',50*15/4.05,'s')],
 'Available sensible inventory is CΔT=750 MJ. Without shedding it is consumed at 5.05 MW, giving 148.51 s; after a 15 s delay, only 133.51 s remain. Immediate shedding changes heat input to 4.05 MW and gives 185.19 s. A delayed shed needs a piecewise balance; do not apply the immediate result after already spending the initial inventory. Local coolant maldistribution and chip thermal resistance can reach limits earlier than the bulk average. Include sensing/actuation power, independent circulation, communication loss, staged IT reduction, conservative trips and proof testing.',
 ['Include circulation heat inside the defined thermal boundary.','Account for control delay and local-versus-average temperature limits.']);

const branchFlow=80/(4.18*10),branchDP=15*branchFlow**2,totalDP=branchDP+30+10;
add('Design and balance an eight-rack manifold','thermal-fluid',
 'Eight identical parallel racks each remove 80 kW with water at 30→40°C. cp=4.18 kJ/(kg K), rho=1000 kg/m³. Each rack path excluding its balancing valve has ΔP=15q² in kPa with q in L/s. Shared piping loses 30 kPa at total design flow. Reserve 10 kPa per rack balancing valve. Pump efficiency=0.70 and motor efficiency=0.90.',
 ['Find rack and total flow.','Find pump differential pressure and electrical input.','Draw the common and parallel pressure paths and select a control reference.','Explain how fouling of one rack affects a constant-speed versus controlled-differential-pressure system.'],
 [n('Mass flow per rack',branchFlow,'kg/s'),n('Total volume flow',8*branchFlow,'L/s'),n('Required differential pressure',totalDP,'kPa'),n('Electrical pump input',totalDP*(8*branchFlow/1000)/(.7*.9),'kW')],
 'Per-rack mass flow is 80/(4.18×10)=1.914 kg/s, numerically 1.914 L/s for the stated density. Total is 15.311 L/s. One rack path loses 15q²≈54.95 kPa; add one balancing valve and the shared loss, giving about 94.95 kPa. Do not sum losses across all eight parallel racks. Electrical power is ΔP Vdot/(eta_p eta_m), about 2.31 kW. Set control at a meaningful remote hydraulic point and verify valve authority, sensor placement, bypass/minimum flow and low-load behavior. In a real network, branch changes and pump response must be solved together.',
 ['Sum series losses along one common-to-common path, not across parallel branches.','Connect pump control to branch flow and balancing requirements.']);

const endForce=2e6*Math.PI*.2**2/4,boltMax=endForce/8+2000*.15/(8*.15**2/2);
add('Check a flange bolt group under pressure and moment','structure',
 'A 200 mm ID closure sees 2 MPa differential pressure and a separate 2.0 kN m overturning moment. Eight equally spaced bolts lie on a 150 mm-radius bolt circle, oriented with bolts at the extreme tension coordinates. Use a rigid linear bolt-group model: direct pressure force shares equally, and moment tensile increment is M y / sum(y²). Each bolt tensile area is 84.3 mm²; allowable nominal tensile stress is 150 MPa. Ignore preload, flange contact, prying and gasket response for this exercise.',
 ['Calculate pressure end force and sum(y²).','Find maximum nominal bolt force and stress.','Assess the supplied elementary allowable.','Explain why a real pressure joint needs more than this bolt-group result.'],
 [n('Pressure end force',endForce/1000,'kN'),n('Maximum nominal bolt force',boltMax/1000,'kN'),n('Maximum nominal bolt stress',boltMax/84.3,'MPa')],
 'Pressure end force is p pi D²/4=62.832 kN. For a uniform circular group sum(y²)=n r²/2=0.090 m². Direct force is 7.854 kN per bolt; maximum moment increment is 2,000×0.15/0.09=3.333 kN. Maximum nominal force is 11.187 kN and stress is 132.71 MPa, below 150 MPa in the stated model. Real joint design must account for preload, member/bolt stiffness, gasket seating and leak-tightness, flange contact, prying, stress concentration, fatigue, thermal cycling and applicable pressure-boundary rules. The toy linear load allocation is not a sealed-joint qualification.',
 ['Use the bolt-group second moment and pressure area with consistent units.','State the contact/preload limits of the nominal linear model.']);

add('Integrate data-center heat recovery without double counting','cycle',
 'A compute chiller removes 8 MW from IT cooling at COP 4. Its condenser heat is available at a source suitable for a heat pump. The heat pump extracts 6 MW from that condenser stream and has heating COP=4. Neglect all other loads and losses. Heat not extracted by the heat pump is rejected to ambient.',
 ['Find chiller input and total condenser heat.','Find heat-pump input, useful heating output and residual ambient rejection.','Close an overall energy balance from IT heat plus both compressors to final sinks.','Draw boundaries and explain why recovered heat does not reduce the stated IT cooling duty.'],
 [n('Chiller electrical input',2,'MW'),n('Heat-pump electrical input',2,'MW'),n('Useful heating output',8,'MW'),n('Residual ambient rejection',4,'MW'),n('Combined electrical input',4,'MW')],
 'Chiller input is 8/4=2 MW and condenser duty is 10 MW. For the heat pump, COPheat=Qhot/W=4 and Qhot=6+W; therefore W=2 MW and Qhot=8 MW. The condenser stream still rejects 10−6=4 MW to ambient. Overall, 8 MW IT heat +2 MW chiller input +2 MW heat-pump input =8 MW useful heating +4 MW ambient rejection. The IT load remains 8 MW; useful recovery reroutes downstream heat. Actual feasibility depends on heat-demand timing, source/sink approach temperatures, compressor maps, return conditions and backup heat rejection.',
 ['Distinguish heating COP from refrigeration COP.','Close nested and overall balances without crediting the same heat twice.']);

add('Specify natural-gas pretreatment before a cold box','cryo',
 'A hypothetical feed contains 900 kg/h methane, 20 kg/h CO2, 2 kg/h water, 78 kg/h N2 and 100 kg/h heavier hydrocarbons. The specified CO2 removal fraction is 99.9%. The water target is 1 ppm by mass relative to the 900 kg/h methane component, not total gas. For a methane-only cold-duty estimate use cp=2.2 kJ/(kg K), inlet 300 K, saturation 112 K and hfg=510 kJ/kg. Ignore other-component cold duty only in that estimate.',
 ['Calculate residual CO2 and required water removal.','Estimate methane-only cooling/liquefaction duty.','Lay out treatment steps and identify composition/solid-formation and product-specification questions.','Explain why neither the methane-only heat estimate nor liquefaction itself guarantees a qualified product.'],
 [n('Residual CO2',20*.001,'kg/h'),n('Required water removal',2-900e-6,'kg/h'),n('Methane-only cold duty',900/3600*(2.2*(300-112)+510),'kW')],
 'Residual CO2 is 0.020 kg/h. Allowed water is 900×1e-6=0.0009 kg/h, so removal is 1.9991 kg/h. Methane-only duty is (900/3600)[2.2(300−112)+510]=230.9 kW. Real treatment and cold-box design require actual specifications and phase/solid data: dehydration, CO2 removal, heavy-hydrocarbon control and any feed-specific contaminants must be addressed. N2 and hydrocarbons can affect product composition, separation, temperature glide and boil-off. The supplied CO2 percentage is an arithmetic target, not evidence that its residual is acceptable at every cold state. Use mixture properties and a full mass/energy balance for actual equipment sizing.',
 ['Respect the explicitly defined ppm/component basis.','Link pretreatment to cold-box phase behavior and the required product specification.']);

add('Plan a controlled LOX fill with an inventory target','cryo',
 'A controlled-pressure LOX tank initially contains 20 tonnes and must finish at 180 tonnes. Inlet liquid rate is constant at 25 kg/s; boil-off leaving the inventory is stipulated to be 0.020 kg/s throughout. Liquid density is 1140 kg/m³. Final liquid may occupy at most 90% of geometric volume; ignore heel and density variation. A backup plan must finish the same mass addition within 3 hours.',
 ['Find fill duration at the stated inlet rate.','Find minimum inlet rate meeting the three-hour inventory requirement under this same boil-off model.','Find required geometric tank volume.','Draw fill, pressure-control and isolation paths and explain which transients and safety functions are outside the model.'],
 [n('Fill duration',160000/(25-.020),'s'),n('Minimum three-hour inlet rate',160000/(3*3600)+.020,'kg/s'),n('Required geometric storage volume',180000/(1140*.9),'m3')],
 'Net accumulation is 25−0.020=24.98 kg/s. Adding 160,000 kg takes 6405.1 s, or 1.779 hours. For three hours, minimum inlet is 160,000/10,800+0.020=14.835 kg/s. Final tank geometry requires 180,000/(1140×0.90)=175.44 m³. Real cooldown, flash, stratification, varying vapor generation, inlet momentum, pressure control and level measurement can change the event. Confirm oxygen-compatible materials/cleanliness, overfill protection, independent relief, approved vent disposition, NPSH and controlled valve transients. The stipulated boil-off is not a relief-sizing result.',
 ['Use net inventory accumulation rather than inlet flow alone.','Separate final geometric storage from the transferred mass and transient protection design.']);

const lateral=1200*1.5*9.81,weight=1200*9.81,uplift=Math.max(0,lateral/1.6-weight/2);
add('Design the equipment skid load path','structure',
 'A rigid 1200 kg skid has CG height 1.0 m. Apply a horizontal equivalent acceleration 1.5g, g=9.81 m/s². Four anchors form two rows 1.6 m apart in the load direction, with two anchors per row. Before overturning, vertical weight shares equally between rows. Assume equal direct shear across four anchors, rigid load distribution and no prying; ignore all other loads.',
 ['Draw the free body and calculate horizontal force and overturning moment.','Find total uplift at the lifting row and nominal uplift per anchor there.','Find nominal direct shear per anchor.','Explain the missing baseplate/contact, combined-load, dynamic and anchorage checks.'],
 [n('Horizontal force',lateral/1000,'kN'),n('Overturning moment',lateral/1000,'kN.m'),n('Uplift per anchor in lifting row',uplift/2/1000,'kN'),n('Direct shear per anchor',lateral/4/1000,'kN')],
 'Horizontal force is 17.658 kN; with 1 m CG height the overturning moment is 17.658 kN m. The moment couple across 1.6 m requires 11.036 kN vertical transfer. Weight supplies 5.886 kN per row, leaving 5.150 kN net uplift on one row or 2.575 kN per anchor there. Direct shear is 4.4145 kN per anchor in the simplified equal-share model. Verify actual contact, preload, plate stiffness, concrete/substrate anchorage, edge distance, interaction of tension/shear, friction assumptions, dynamic amplification, fatigue and equipment internal loads. A nominal equivalent-static model does not prove seismic qualification.',
 ['Close overturning equilibrium including the stabilizing weight.','Keep explicit the assumed contact and equal-sharing model.']);

add('Reject an infeasible liquefier requirement and redesign it','cycle',
 'A test stand requests 500 kW net cold duty. Available electrical service is 1.00 MW total; fixed auxiliary draw is 0.10 MW. Two hypothetical cycles have net refrigeration COPs, excluding these auxiliaries, of 0.16 for N2 expansion and 0.28 for mixed refrigerant. For a maximum methane-production estimate use 923.6 kJ/kg total cold duty per kg of product. Assume both routes can otherwise meet the temperature and safety requirements.',
 ['Find total electrical demand for each route at 500 kW cold.','Find maximum available cold duty for each route under the electrical constraint.','Find maximum methane rate for the mixed-refrigerant route under that constraint.','Propose feasible alternatives and explain why choosing the higher COP does not by itself satisfy the original requirement.'],
 [n('N2 total electrical demand at target',.5/.16+.1,'MW'),n('MR total electrical demand at target',.5/.28+.1,'MW'),n('MR maximum available cold duty',.9*.28,'MW'),n('MR maximum methane rate',(.9*.28*1000)/923.6*3600,'kg/h')],
 'At 500 kW cold, total demands are 0.5/0.16+0.10=3.225 MW for N2 and 0.5/0.28+0.10=1.886 MW for MR. Neither meets the 1 MW supply. Available compressor input is 0.90 MW; cold capacities are 0.144 and 0.252 MW. The MR product estimate is 252/923.6=0.27285 kg/s, or about 982.2 kg/h. Feasible changes include more electrical capacity, lower production requirement, qualified external cold supply, or time-shifted storage if the duty cycle permits it. Each needs an explicit balance and operating constraint. Net COPs cannot be transplanted to a different temperature or part-load regime without evidence.',
 ['Apply the auxiliary load and hard electrical capacity before cycle ranking.','Propose a feasible revised requirement with a quantified consequence.']);

const vOpt=.05/(Math.PI*.2**2/4),dpOpt=(.02*500/.2+20)*1000*vOpt**2/2,pOpt=.05*dpOpt/(.7*.95)/1000,annuity=(1-1.08**-10)/.08;
add('Choose pipe diameter on whole-life cost and velocity','thermal-fluid',
 'A water loop carries 0.050 m³/s through 500 m of pipe. Use rho=1000 kg/m³, fixed Darcy f=0.020 and total fitting K=20 for every candidate. Static head is zero. Candidate IDs are 150, 200 and 250 mm with installed costs $100,000, $150,000 and $220,000. Velocity limit is 2 m/s. Pump/motor efficiencies are 0.70/0.95; operate 8000 h/year at $0.12/kWh. Use 10 years and discount rate 8%, ignoring maintenance, replacement and salvage.',
 ['Calculate velocity, loss and electrical power for each candidate.','Reject candidates violating velocity.','Calculate present cost = installed cost + annual electricity cost times the annuity factor.','Select the lowest-cost feasible option and explain sensitivity to f, tariffs, hours and flow uncertainty.'],
 [n('Velocity in 200 mm candidate',vOpt,'m/s'),n('Pressure loss in 200 mm candidate',dpOpt/1000,'kPa'),n('Electrical input for 200 mm candidate',pOpt,'kW'),n('Present cost for 200 mm candidate',150000+pOpt*8000*.12*annuity,'USD')],
 'For each diameter, v=4Vdot/(pi D²), Δp=(fL/D+K)rho v²/2 and Pel=Vdot Δp/(eta_p eta_m). The 150 mm candidate exceeds 2 m/s and is infeasible. For 200 mm, v=1.5915 m/s, Δp≈88.66 kPa and Pel≈6.67 kW. The annuity factor is [1−(1.08)^−10]/0.08=6.7101; present cost is about $192,940. The feasible 250 mm option has lower energy but higher present cost, about $235,100, under these assumptions. Thus 200 mm wins this restricted comparison. Recalculate actual friction, fitting losses, operating points, fouling, installation constraints, expansion and changing duty profiles before final selection.',
 ['Apply a feasibility screen before the discounted-cost ranking.','Use flow-dependent velocity and hydraulic power rather than a diameter-only cost rule.']);

